const raw = String($('Normalize Input').first().json.text ?? '').trim();
const normalized = raw.toLowerCase();
const skip = normalized === 'skip_description' || normalized === 'pular' || normalized === 'sem descrição' || normalized === 'sem descricao' || normalized === '-';
if (skip) return [{ json: { valid: true, description: null } }];
if (raw.length > 255) return [{ json: { valid: false, description: raw, reason: 'too_long' } }];
return [{ json: { valid: true, description: raw } }];

